  var C = { K: '#1E1A4D', V: '#7B52EE', V2: '#C9B8FF', V3: '#EDE7FF', T: '#0B9FB3', T3: '#E3F8FB', G: '#FFB300', G3: '#FFF4D6', PK: '#DB2777', PK2: '#F472B6', GR: '#10B981', OR: '#F97316' };
  function pic(s) { return '<svg viewBox="0 0 120 120" fill="none" stroke-linecap="round" stroke-linejoin="round" font-family="Nunito, sans-serif" font-weight="900">' + s + '</svg>'; }
