      // Тэгш өнцөгт бүр 24 × 16 хайрцгийн голд; хайрцгийн зүүн доод булан (OX, OY) — 0 нь x, y мужид орохгүй тул тэнхлэг зургийг огтлохгүй.
      const PR305 = [[12, 8], [18, 12], [20, 15], [21, 14], [24, 16], [16, 9]];
      const OX305 = 3, OY305 = 2.4;
      function gcd305(a, b) { return b ? gcd305(b, a % b) : a; }
      function box305(k) { const W = PR305[k][0], H = PR305[k][1]; return { W: W, H: H, x0: OX305 + (24 - W) / 2, y0: OY305 + (16 - H) / 2 }; }
      function lines305(P) {
        const b = box305(P.k), d = P.d, nW = Math.floor(b.W / d), nH = Math.floor(b.H / d), L = [];
        const xe = b.x0 + nW * d, ye = b.y0 + nH * d, x1 = b.x0 + b.W, y1 = b.y0 + b.H;
        for (let y = b.y0 + 0.06; y < y1 - 0.02; y += 0.12) {   // будалт (нягт зураас)
          if (y < ye) { L.push([b.x0, y, xe, y, '#E4DAFF', 0]); if (xe < x1) L.push([xe, y, x1, y, '#FBCFE8', 0]); }
          else L.push([b.x0, y, x1, y, '#FBCFE8', 0]);
        }
        for (let i = 0; i <= nW; i++) L.push([b.x0 + i * d, b.y0, b.x0 + i * d, ye, C.V, 0]);
        for (let j = 0; j <= nH; j++) L.push([b.x0, b.y0 + j * d, xe, b.y0 + j * d, C.V, 0]);
        L.push([b.x0, b.y0, x1, b.y0, C.K, 0], [x1, b.y0, x1, y1, C.K, 0], [x1, y1, b.x0, y1, C.K, 0], [b.x0, y1, b.x0, b.y0, C.K, 0]);
        return L;
      }
      // Талын урт (доор — өргөн, зүүн талд — өндөр), зөвхөн сонгосон тэгш өнцөгтөд харагдана
      function lab305(k, x, y, s, ly, la) { return { fn: function (xx, P) { return xx === x && P.k === k ? y : NaN; }, c: '#4B4475', lb: s, lx: x, ly: ly, la: la }; }
      const F305 = [];
