      // Алхам 1 — бүхэл хэсгийг бүхлээр нь, 2–4 — аравны, зууны, мянганы хэсгийг жишнэ. Төгсгөлд нэмсэн тэг — саарал.
      const PR311 = [['0.38', '0.5'], ['10.2', '9.85'], ['0.56', '0.506'], ['35.172', '35.17'], ['2.7', '2.70']];
      const CX311 = [1.4, 2.6, 4.1, 5.3, 6.5], DOT311 = 3.35, HW311 = 0.5, RY311 = [3.95, 3.1], RH311 = 0.36, SY311 = 2.25;
      const PV311 = ['10', '1', '0.1', '0.01', '0.001'];
