        if (v && !L.add) t += '\n' + PL313[v.e] + ': $' + v.a + '-' + v.b + '$ болохгүй тул зүүн талын орноос $1$ зээлнэ: $' + (v.a + 10) + '-' + v.b + '=' + v.d + '$.';
